1	/*
2	 * AI模拟面试官 — 状态机实现
3	 * 负责：B同学
4	 * IDLE -> RECORDING -> UPLOADING -> PLAYING -> IDLE
5	 */
6	
7	#include <stdio.h>
8	#include <fcntl.h>
9	#include <unistd.h>
10	#include <sys/ioctl.h>
11	#include <nuttx/ioexpander/gpio.h>
12	#include "state_machine.h"
13	
14	/* LED GPIO 引脚定义 */
15	#define LED1_GPIO  0   /* GPIO0 控制 LED1 */
16	#define LED2_GPIO  2   /* GPIO2 控制 LED2 */
17	
18	/* LED 文件描述符 */
19	static int g_led1_fd = -1;
20	static int g_led2_fd = -1;
21	
22	static system_state_t g_current_state = STATE_IDLE;
23	static int g_retry_count = 0;
24	#define MAX_RETRY_COUNT 3
25	
26	static const char* state_names[] = {"IDLE", "RECORDING", "UPLOADING", "PLAYING", "ERROR"};
27	static const char* event_names[] = {"BUTTON_PRESS", "RECORD_DONE", "RECORD_TIMEOUT", "UPLOAD_SUCCESS", "UPLOAD_FAIL", "PLAY_DONE", "RETRY", "ERROR"};
28	
29	static system_state_t get_next_state(system_state_t current, system_event_t event)
30	{
31	    switch (current) {
32	        case STATE_IDLE:
33	            if (event == EVENT_BUTTON_PRESS) { g_retry_count = 0; return STATE_RECORDING; }
34	            return current;
35	        case STATE_RECORDING:
36	            if (event == EVENT_RECORD_DONE || event == EVENT_RECORD_TIMEOUT) return STATE_UPLOADING;
37	            if (event == EVENT_ERROR) return STATE_IDLE;
38	            return current;
39	        case STATE_UPLOADING:
40	            if (event == EVENT_UPLOAD_SUCCESS) return STATE_PLAYING;
41	            if (event == EVENT_UPLOAD_FAIL) {
42	                g_retry_count++;
43	                if (g_retry_count >= MAX_RETRY_COUNT) return STATE_IDLE;
44	                return STATE_ERROR;
45	            }
46	            return current;
47	        case STATE_PLAYING:
48	            if (event == EVENT_PLAY_DONE) return STATE_IDLE;
49	            return current;
50	        case STATE_ERROR:
51	            if (event == EVENT_BUTTON_PRESS) { g_retry_count = 0; return STATE_IDLE; }
52	            if (event == EVENT_RETRY) return STATE_UPLOADING;
53	            return current;
54	    }
55	    return STATE_IDLE;
56	}
57	
58	static void update_led_by_state(system_state_t state)
59	{
60	    /* 先关闭所有 LED */
61	    if (g_led1_fd >= 0) {
62	        ioctl(g_led1_fd, GPIOC_WRITE, 1);  /* LED1 灭 */
63	    }
64	    if (g_led2_fd >= 0) {
65	        ioctl(g_led2_fd, GPIOC_WRITE, 1);  /* LED2 灭 */
66	    }
67	
68	    switch (state) {
69	        case STATE_IDLE:
70	            /* 待机: LED1 常亮 */
71	            if (g_led1_fd >= 0) {
72	                ioctl(g_led1_fd, GPIOC_WRITE, 0);  /* LED1 亮 */
73	            }
74	            break;
75	        case STATE_RECORDING:
76	            /* 录音中: LED1 快闪 (200ms间隔) */
77	            printf("[LED] 录音中 - LED1 快闪\n");
78	            break;
79	        case STATE_UPLOADING:
80	            /* 上传中: LED1 慢闪 (800ms间隔) */
81	            printf("[LED] 上传中 - LED1 慢闪\n");
82	            break;
83	        case STATE_PLAYING:
84	            /* 播放中: LED2 常亮 */
85	            if (g_led2_fd >= 0) {
86	                ioctl(g_led2_fd, GPIOC_WRITE, 0);  /* LED2 亮 */
87	            }
88	            break;
89	        case STATE_ERROR:
90	            /* 错误: LED1 三短闪循环 */
91	            printf("[LED] 错误状态 - LED1 三短闪\n");
92	            break;
93	    }
94	}
95	
96	void state_machine_init(void)
97	{
98	    /* 初始化 LED GPIO */
99	    g_led1_fd = open("/dev/gpio0", O_RDWR);
100	    if (g_led1_fd < 0) {
101	        printf("[StateMachine] 警告: 无法打开 LED1 GPIO (GPIO0)\n");
102	    } else {
103	        /* 设置为输出模式 */
104	        ioctl(g_led1_fd, GPIOC_SETPINTYPE, GPIO_OUTPUT_PIN);
105	        /* 初始状态: LED1 灭 */
106	        ioctl(g_led1_fd, GPIOC_WRITE, 1);
107	        printf("[StateMachine] LED1 GPIO (GPIO0) 初始化成功\n");
108	    }
109	
110	    g_led2_fd = open("/dev/gpio2", O_RDWR);
111	    if (g_led2_fd < 0) {
112	        printf("[StateMachine] 警告: 无法打开 LED2 GPIO (GPIO2)\n");
113	    } else {
114	        /* 设置为输出模式 */
115	        ioctl(g_led2_fd, GPIOC_SETPINTYPE, GPIO_OUTPUT_PIN);
116	        /* 初始状态: LED2 灭 */
117	        ioctl(g_led2_fd, GPIOC_WRITE, 1);
118	        printf("[StateMachine] LED2 GPIO (GPIO2) 初始化成功\n");
119	    }
120	
121	    g_current_state = STATE_IDLE;
122	    g_retry_count = 0;
123	    printf("[StateMachine] 初始化完成，当前状态: %s\n", state_names[g_current_state]);
124	    update_led_by_state(STATE_IDLE);
125	}
126	
127	void state_machine_post_event(system_event_t event)
128	{
129	    system_state_t new_state = get_next_state(g_current_state, event);
130	    if (new_state != g_current_state) {
131	        printf("[StateMachine] %s --[%s]--> %s\n", state_names[g_current_state], event_names[event], state_names[new_state]);
132	        g_current_state = new_state;
133	        update_led_by_state(new_state);
134	        switch (new_state) {
135	            case STATE_RECORDING: printf("[StateMachine] 开始录音...\n"); break;
136	            case STATE_UPLOADING: printf("[StateMachine] 开始上传音频...\n"); break;
137	            case STATE_PLAYING:   printf("[StateMachine] 开始播放...\n"); break;
138	            case STATE_ERROR:     printf("[StateMachine] 错误状态，等待处理...\n"); break;
139	            default: break;
140	        }
141	    }
142	}
143	
144	system_state_t state_machine_get_current_state(void) { return g_current_state; }
145	int state_machine_is_busy(void) {
146	    return (g_current_state == STATE_RECORDING || g_current_state == STATE_UPLOADING || g_current_state == STATE_PLAYING);
147	}
148	
149	/* LED 闪烁控制变量 */
150	static int g_led_blink_state = 0;  /* 闪烁状态: 0=灭, 1=亮 */
151	static int g_led_blink_count = 0;  /* 闪烁计数 */
152	static int g_led_blink_pattern = 0; /* 闪烁模式: 0=快闪, 1=慢闪, 2=三短闪 */
153	
154	void state_machine_update_led(void)
155	{
156	    switch (g_current_state) {
157	        case STATE_IDLE:
158	            /* 待机: LED1 常亮 */
159	            if (g_led1_fd >= 0) {
160	                ioctl(g_led1_fd, GPIOC_WRITE, 0);  /* LED1 亮 */
161	            }
162	            break;
163	
164	        case STATE_RECORDING:
165	            /* 录音中: LED1 快闪 (200ms间隔) */
166	            if (g_led1_fd >= 0) {
167	                g_led_blink_state = !g_led_blink_state;
168	                ioctl(g_led1_fd, GPIOC_WRITE, g_led_blink_state ? 1 : 0);
169	            }
170	            break;
171	
172	        case STATE_UPLOADING:
173	            /* 上传中: LED1 慢闪 (800ms间隔) */
174	            if (g_led1_fd >= 0) {
175	                g_led_blink_state = !g_led_blink_state;
176	                ioctl(g_led1_fd, GPIOC_WRITE, g_led_blink_state ? 1 : 0);
177	            }
178	            break;
179	
180	        case STATE_PLAYING:
181	            /* 播放中: LED2 常亮 */
182	            if (g_led2_fd >= 0) {
183	                ioctl(g_led2_fd, GPIOC_WRITE, 0);  /* LED2 亮 */
184	            }
185	            break;
186	
187	        case STATE_ERROR:
188	            /* 错误: LED1 三短闪循环 */
189	            if (g_led1_fd >= 0) {
190	                g_led_blink_count++;
191	                if (g_led_blink_count <= 6) {  /* 3次闪烁 = 6次状态切换 */
192	                    g_led_blink_state = !g_led_blink_state;
193	                    ioctl(g_led1_fd, GPIOC_WRITE, g_led_blink_state ? 1 : 0);
194	                } else if (g_led_blink_count <= 12) {  /* 停顿 */
195	                    ioctl(g_led1_fd, GPIOC_WRITE, 1);  /* LED1 灭 */
196	                } else {
197	                    g_led_blink_count = 0;  /* 重新开始 */
198	                }
199	            }
200	            break;
201	    }
202	}
203	
204	void led_set(led_color_t color, led_mode_t mode)
205	{
206	    printf("[LED] 颜色=%d, 模式=%d\n", color, mode);
207	
208	    /* 根据颜色选择 GPIO */
209	    int fd = -1;
210	    if (color == LED_GREEN || color == LED_RED) {
211	        fd = g_led1_fd;  /* LED1 用于绿色/红色指示 */
212	    } else if (color == LED_BLUE) {
213	        fd = g_led2_fd;  /* LED2 用于蓝色指示 */
214	    }
215	
216	    if (fd < 0) {
217	        printf("[LED] 错误: GPIO 未初始化\n");
218	        return;
219	    }
220	
221	    /* 根据模式控制 LED */
222	    switch (mode) {
223	        case LED_MODE_ON:
224	            /* 常亮 - 低电平有效 */
225	            ioctl(fd, GPIOC_WRITE, 0);
226	            break;
227	        case LED_MODE_OFF:
228	            /* 熄灭 - 高电平有效 */
229	            ioctl(fd, GPIOC_WRITE, 1);
230	            break;
231	        case LED_MODE_BLINK:
232	            /* 闪烁 - 快闪 (200ms间隔) */
233	            printf("[LED] 闪烁模式需要在主循环中实现\n");
234	            break;
235	        case LED_MODE_BREATH:
236	            /* 呼吸灯 - 慢闪 (800ms间隔) */
237	            printf("[LED] 呼吸灯模式需要在主循环中实现\n");
238	            break;
239	        default:
240	            break;
241	    }
242	}
