/* state_machine 迁移表的 PC 端验证（临时脚本，不入库）。
 *
 * 为什么能做：state_machine.c 里所有 GPIO 操作都以 `fd >= 0` 为前提，
 * 而 PC 上 /dev/gpioN 打不开 → fd = -1 → 写 LED 全部静默跳过。
 * 于是**迁移逻辑可以脱离硬件跑**，只要给 ioctl 一个空实现。
 */
#include <stdio.h>
#include "state_machine.h"

int fails;

static void check(system_state_t expect, system_state_t got, const char *what)
{
    int ok = (expect == got);
    printf("  %-52s %s\n", what, ok ? "OK" : "**FAIL**");
    if (!ok) {
        fails++;
        printf("      期望 %d，实际 %d\n", (int)expect, (int)got);
    }
}

#define POST(e)     state_machine_post_event(e)
#define CUR         state_machine_get_current_state()

int main(void)
{
    state_machine_init();
    printf("state_machine 迁移表验证\n\n");

    printf("[初始]\n");
    check(STATE_IDLE, CUR, "初始化后为 IDLE");

    printf("\n[正常一轮]\n");
    POST(EVENT_BUTTON_PRESS);
    check(STATE_RECORDING, CUR, "IDLE --BUTTON_PRESS--> RECORDING");
    POST(EVENT_RECORD_DONE);
    check(STATE_UPLOADING, CUR, "RECORDING --RECORD_DONE--> UPLOADING");
    POST(EVENT_UPLOAD_SUCCESS);
    check(STATE_PLAYING, CUR, "UPLOADING --UPLOAD_SUCCESS--> PLAYING");
    POST(EVENT_PLAY_DONE);
    check(STATE_IDLE, CUR, "PLAYING --PLAY_DONE--> IDLE");

    printf("\n[★ 本次修复：上传期间按 K2]\n");
    POST(EVENT_BUTTON_PRESS);
    POST(EVENT_RECORD_DONE);
    check(STATE_UPLOADING, CUR, "先走到 UPLOADING");
    POST(EVENT_ERROR);
    check(STATE_IDLE, CUR, "UPLOADING --ERROR--> IDLE（修复前会卡在 UPLOADING）");

    printf("\n[原有路径不能坏]\n");
    POST(EVENT_BUTTON_PRESS);
    POST(EVENT_RECORD_DONE);
    POST(EVENT_UPLOAD_FAIL);
    check(STATE_ERROR, CUR, "UPLOADING --UPLOAD_FAIL--> ERROR（第 1 次失败）");
    POST(EVENT_BUTTON_PRESS);
    check(STATE_IDLE, CUR, "ERROR --BUTTON_PRESS--> IDLE");

    POST(EVENT_BUTTON_PRESS);
    check(STATE_RECORDING, CUR, "IDLE --BUTTON_PRESS--> RECORDING");
    POST(EVENT_ERROR);
    check(STATE_IDLE, CUR, "RECORDING --ERROR--> IDLE（录音时取消，一直如此）");

    printf("\n[连续失败 3 次应回 IDLE，而不是停在 ERROR]\n");
    POST(EVENT_BUTTON_PRESS);
    POST(EVENT_RECORD_DONE);
    POST(EVENT_UPLOAD_FAIL);
    check(STATE_ERROR, CUR, "第 1 次 UPLOAD_FAIL -> ERROR");
    POST(EVENT_RETRY);
    check(STATE_UPLOADING, CUR, "ERROR --RETRY--> UPLOADING");
    POST(EVENT_UPLOAD_FAIL);
    check(STATE_ERROR, CUR, "第 2 次 UPLOAD_FAIL -> ERROR");
    POST(EVENT_RETRY);
    POST(EVENT_UPLOAD_FAIL);
    check(STATE_IDLE, CUR, "第 3 次 UPLOAD_FAIL -> IDLE");

    printf("\n%s（失败 %d 项）\n", fails ? "**有失败**" : "全部通过", fails);
    return fails != 0;
}

