//   /                  最近一场（默认，实时轮询）—— 公共设备的主路径：
//                      面完走过来打开网页，看到的就是刚那一场
//   /?session_id=xxx   指定某一场
//   /history           历史列表
//   /text              文字演练（无硬件的降级通道，见 app.py 里那个端点的注释）
//
// 不用前端路由（hash）而用真实路径：URL 能直接收藏/分享，刷新后停在原处 ——
// 对"贴在板子旁边的那张纸卡上的网址"来说，这点很重要。
var IS_LIST = /^\/history\/?$/.test(location.pathname);
var IS_TEXT = /^\/text\/?$/.test(location.pathname);
var SID = "";
try { SID = new URLSearchParams(location.search).get("session_id") || ""; } catch (e) { SID = ""; }

// ---------- 文字演练（/text） ----------
//
// 无硬件的降级通道：打字代替说话，**不走 TTS**（每轮省掉两次语音调用）。
// 每一步都落在与设备链路**同一个会话机制**上 —— 所以它产生的记录，在 /history
// 里和板子那几场并列，报告、评分、逐题复盘一模一样。

// 岗位清单：必须与题库里的 6 个岗位名**一字不差** —— 对不上时云端不报错，
// 只会静默退化成"没有参考题的自由提问"（见 cloud/question_bank.py 的别名表）。
var ROLES = ["AI 应用开发", "AI Agent 开发", "大模型算法工程师",
             "AI/ML Engineer", "Data Scientist", "Data Analyst"];

var textRole = ROLES[0];
var starting = false;

function renderStarter() {
  var opts = "";
  for (var i = 0; i < ROLES.length; i++) {
    opts += '<option value="' + esc(ROLES[i]) + '">' + esc(ROLES[i]) + "</option>";
  }
  elStarter.innerHTML =
    '<div class="starter">' +
      "<h2>文字演练</h2>" +
      '<p class="warn">这是<b>无硬件的降级演练</b>：打字练不出语速、卡壳和口头语 ——' +
        "正式使用请对着开发板说。</p>" +
      '<label>面试岗位 <select id="roleSel">' + opts + "</select></label>" +
      '<button class="btn" id="startBtn" ' +
        'style="font-size:14px;padding:9px 18px">开始面试</button>' +
    "</div>";
  document.getElementById("startBtn").addEventListener("click", startText);
}

function textPost(payload) {
  return fetch("/api/interview/text", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  }).then(function (r) { return r.json(); });
}

function startText() {
  if (starting) { return; }          // 防连点：点两下会开出两场会话
  starting = true;
  var sel = document.getElementById("roleSel");
  textRole = sel ? sel.value : ROLES[0];
  textPost({ role: textRole, state: "start" })
    .then(function (d) {
      if (!d.session_id) { throw new Error(d.error || "创建会话失败"); }
      SID = d.session_id;
      elStarter.style.display = "none";
      elComposer.style.display = "flex";
      // 会话写进地址栏：刷新还停在这一场（与另外两个视图同一个规矩）
      history.replaceState(null, "", "/text?session_id=" + encodeURIComponent(SID));
      tick();
      elAnswerBox.focus();
    })
    .catch(function (e) { setStatus("err", e.message); })
    .then(function () { starting = false; });
}

function sendText() {
  var text = (elAnswerBox.value || "").trim();
  if (!text || !SID || elSendBtn.disabled) { return; }
  elSendBtn.disabled = true;
  textPost({ session_id: SID, role: textRole, text: text })
    .then(function (d) {
      if (d.error) { throw new Error(d.error); }
      elAnswerBox.value = "";
      tick();                        // 立刻拉一次，不必等下一轮轮询
    })
    .catch(function (e) { setStatus("err", e.message); })
    .then(function () { elSendBtn.disabled = false; elAnswerBox.focus(); });
}

// Ctrl/⌘+Enter 发送（与 myagent 的习惯一致）；单独 Enter 换行，不打字误发。
elAnswerBox.addEventListener("keydown", function (e) {
  if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {
    e.preventDefault();
    sendText();
  }
});
elSendBtn.addEventListener("click", sendText);

// ---------- 启动 ----------

